[message 46781 | 2025-01-22T05:23:17+00:00] #include <iostream>
#include <vector>
#include <ctime>

using namespace std;

int main() {
 const int SIZE = 1000;

 // تعریف ماتریس‌ها
 vector<vector<int>> A(SIZE, vector<int>(SIZE));
 vector<vector<int>> B(SIZE, vector<int>(SIZE));
 vector<vector<int>> C(SIZE, vector<int>(SIZE, 0));

 // مقداردهی اولیه به ماتریس‌های A و B
 srand(time(0)); // مقداردهی برای اعداد تصادفی
 for (int i = 0; i < SIZE; i++) {
 for (int j = 0; j < SIZE; j++) {
 A[i][j] = rand() % 100; // مقدار تصادفی بین 0 تا 99
 B[i][j] = rand() % 100; // مقدار تصادفی بین 0 تا 99
 }
 }

 // شروع زمان‌سنجی
 clock_t start = clock();

 // ضرب ماتریس A و B و ذخیره در C
 for (int i = 0; i < SIZE; i++) {
 for (int j = 0; j < SIZE; j++) {
 for (int k = 0; k < SIZE; k++) {
 C[i][j] += A[i][k] * B[k][j];
 }
 }
 }

 // پایان زمان‌سنجی
 clock_t end = clock();

 // محاسبه زمان اجرا
 double elapsed_time = double(end - start) / CLOCKS_PER_SEC;
 cout << "زمان اجرای ضرب ماتریسی: " << elapsed_time << " ثانیه" << endl;

 return 0;
}
